import { extname } from "../../platform/compat/path/basic-operations.js";
export const CHUNKS_PER_FILE = 500;
export function readPartPaths(value) {
    return Array.isArray(value)
        ? [
            ...new Set(value.filter((path) => typeof path === "string" && path.trim().length > 0)),
        ]
        : [];
}
export function buildChunkFilePaths(filePath, chunkCount) {
    const extension = extname(filePath);
    const stem = filePath.slice(0, filePath.length - extension.length);
    return Array.from({ length: Math.ceil(chunkCount / CHUNKS_PER_FILE) }, (_, index) => index === 0 ? filePath : `${stem}.part-${index}${extension}`);
}
export function activeDocumentPaths(document, fallback) {
    return document.filePaths?.length
        ? [...new Set(document.filePaths)]
        : [document.filePath ?? fallback];
}
export function retiredDocumentPaths(document, fallback) {
    const active = new Set(activeDocumentPaths(document, fallback));
    return [...new Set(document.cleanupFilePaths ?? [])].filter((path) => !active.has(path));
}
export function documentPartsMetadata(activePaths, cleanupPaths) {
    const filePath = activePaths[0];
    if (!filePath)
        throw new Error("Document has no file parts");
    const retired = [...new Set(cleanupPaths)].filter((path) => !activePaths.includes(path));
    return {
        filePath,
        ...(activePaths.length > 1 ? { filePaths: activePaths } : {}),
        ...(retired.length ? { cleanupFilePaths: retired } : {}),
    };
}
export function metadataWriteOutcome(activePaths, observedPaths, upstreamStatus) {
    if (!observedPaths)
        return "unknown";
    const observed = new Set(observedPaths);
    if (observed.size === new Set(activePaths).size && activePaths.every((path) => observed.has(path)))
        return "committed";
    return typeof upstreamStatus === "number" && upstreamStatus >= 400 && upstreamStatus < 500 &&
        upstreamStatus !== 408
        ? "rejected"
        : "unknown";
}
export async function retireDocumentParts(paths, remove) {
    const failures = [];
    for (const path of new Set(paths)) {
        try {
            await remove(path);
        }
        catch (error) {
            failures.push({ path, error });
        }
    }
    return failures;
}
